<script setup>
import { useDataForgeWorkspace } from '../../../composables/useDataForgeWorkspace'
const { knowledgeBases,selectedBaseId,baseDetail,recordQuery,recordPage,lineage,selectBase,showLineage,openTaskWizard,formatTime,recordSummary,recordContent }=useDataForgeWorkspace()
function locatorText(locator = {}) {
  const parts = []
  if (locator.page_number) parts.push(`第 ${locator.page_number} 页`)
  if (locator.line_number) parts.push(`第 ${locator.line_number} 行`)
  if (locator.paragraph_index) parts.push(`第 ${locator.paragraph_index} 段`)
  if (locator.table_index) parts.push(`表格 ${locator.table_index} / 第 ${locator.row_index} 行`)
  if (locator.chunk_character_start != null) parts.push(`字符 ${locator.chunk_character_start}–${locator.chunk_character_end}`)
  return parts.join(' · ') || `源记录 ${Number(locator.source_record_index || 0) + 1}`
}
function indexStatus(item = {}) {
  return {unindexed:'待索引',pending:'待索引',indexing:'索引中',validating:'校验中',available:'可检索',failed:'索引失败',cancelled:'已取消'}[item.index_status] || '待索引'
}
function indexStatusClass(item = {}) {
  return item.index_status === 'available' ? 'available' : item.index_status === 'failed' ? 'failed' : 'pending'
}
</script>
<template><section class="page"><div class="section-command"><div><span class="eyebrow">Assets</span><b>关系库中的规范知识记录是事实来源，索引是可重建投影</b></div><span class="status available"><i></i>知识资产层</span></div><div class="content-split knowledge-split"><article class="panel list-panel"><div class="panel-heading"><div><span class="eyebrow">知识资产目录</span><h2>{{ knowledgeBases.length }} 个知识库</h2></div></div><div class="entity-list"><button v-for="base in knowledgeBases" :key="base.id" class="entity-row" :class="{selected:selectedBaseId===base.id}" @click="selectBase(base.id)"><span class="file-badge knowledge">KB</span><span><b>{{ base.name }}</b><small>{{ base.knowledge_type_name }} · {{ base.record_count }} 条 · {{ indexStatus(base) }}</small></span></button></div><div v-if="!knowledgeBases.length" class="empty-state"><p>处理任务完成后，资产会出现在这里。</p><button class="ghost-button" @click="openTaskWizard">新建任务</button></div></article><article class="panel detail-panel"><template v-if="baseDetail"><div class="panel-heading"><div><span class="eyebrow">资产详情</span><h2>{{ baseDetail.knowledge_base.name }}</h2></div><span class="status" :class="indexStatusClass(baseDetail.knowledge_base)"><i></i>{{ indexStatus(baseDetail.knowledge_base) }}</span></div><div class="detail-summary"><div><span>知识类型</span><b>{{ baseDetail.knowledge_base.knowledge_type_name }}</b></div><div><span>标准记录</span><b>{{ baseDetail.knowledge_base.record_count }}</b></div><div><span>索引版本</span><b>{{ baseDetail.knowledge_base.index_version ? `V${baseDetail.knowledge_base.index_version}` : '尚未建立' }}</b></div><div><span>创建时间</span><b>{{ formatTime(baseDetail.knowledge_base.created_at) }}</b></div></div><form class="record-search" @submit.prevent="selectBase(selectedBaseId,1)"><label><span>搜索记录或来源</span><input v-model="recordQuery" placeholder="输入关键词"/></label><button class="ghost-button">搜索</button></form><div class="record-list"><button v-for="(record,index) in baseDetail.records" :key="record.id" @click="showLineage(record.id)"><span>{{ (recordPage-1)*30+index+1 }}</span><span><b>{{ recordSummary(record) }}</b><small>来源：{{ record.source_name }} · V{{ record.source_version_no }}</small></span><em>查看溯源</em></button></div><div class="pagination"><button class="ghost-button" :disabled="recordPage<=1" @click="selectBase(selectedBaseId,recordPage-1)">上一页</button><span>{{ recordPage }} / {{ baseDetail.pagination.pages }}</span><button class="ghost-button" :disabled="recordPage>=baseDetail.pagination.pages" @click="selectBase(selectedBaseId,recordPage+1)">下一页</button></div></template><div v-else class="empty-state">选择知识库查看记录</div></article></div><article v-if="lineage" class="panel comparison-panel"><div class="panel-heading"><div><span class="eyebrow">记录级溯源</span><h2>处理前后对照</h2></div><button class="text-button" @click="lineage=null">关闭</button></div><div class="compare-grid"><section><header><span>源记录</span><b>{{ lineage.source_name }} · V{{ lineage.source_version_no }}</b><small>{{ locatorText(lineage.source_locator) }}</small></header><pre>{{ lineage.source_locator?.source_excerpt||'暂无源片段' }}</pre></section><section class="after"><header><span>知识记录</span><b>{{ lineage.knowledge_type_name }}</b></header><pre>{{ recordContent(lineage.data) }}</pre></section></div></article></section></template>
